<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;600&amp;family=Helvetica:wght@400;700&amp;display=swap');

        body {
            font-family: 'Times New Roman', serif;
            max-width: 800px;
            margin: 40px auto;
            padding: 20px;
            line-height: 1.4;
            color: #000;
            background: #fff;
        }

        .header {
            text-align: center;
            margin-bottom: 30px;
        }

        .title {
            font-size: 24px;
            font-weight: 600;
            margin: 10px 0;
        }

        .date {
            font-size: 14px;
            margin-top: 5px;
        }

        .columns {
            display: flex;
            gap: 40px;
            margin: 30px 0;
        }

        .column {
            flex: 1;
        }

        .left-col {
            width: 45%;
        }

        .right-col {
            width: 55%;
        }

        p {
            margin: 12px 0;
            text-align: justify;
        }

        .centered {
            text-align: center;
            font-style: italic;
            margin: 20px 0;
        }

        .placeholder {
            width: 100%;
            height: 120px;
            background: #f5f5f5;
            border: 1px solid #ccc;
            margin: 20px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            color: #666;
            text-align: center;
        }

        .placeholder img {
            max-width: 100%;
            max-height: 100%;
            object-fit: contain;
        }

        .signature {
            margin-top: 40px;
            text-align: right;
        }
    </style>
</head>
<body>
    <div class="header">
        <div style="font-size: 18px; font-weight: 700;">[Organization Logo / Header]</div>
        <div class="title">Document Title</div>
        <div class="date">[Date]</div>
    </div>

    <div class="columns">
        <!-- Left column -->
        <div class="column left-col">
            <p>[Text block 1 - left aligned]</p>
            <p>[Text block 2 - left aligned]</p>

            <div class="placeholder" style="height: 80px;">
                [Diagram / Chart / Image: left side]
            </div>

            <p>[Text block 3 - left aligned]</p>
        </div>

        <!-- Right column -->
        <div class="column right-col">
            <p>[Text block 1 - right column]</p>
            <p>[Text block 2 - right column]</p>

            <div class="placeholder" style="height: 100px;">
                [Diagram / Chart / Image: right side]
            </div>

            <p>[Text block 3 - right column]</p>
        </div>
    </div>

    <div class="signature">
        <p>Signature / Name<br>[Date]</p>
    </div>

    <div class="centered">
        [Center-aligned text or footer]
    </div>
</body>
</html>
